"""Allowlist export from private_root into public_root."""

from __future__ import annotations

import fnmatch
import json
import shutil
import subprocess
from datetime import datetime, timezone
from pathlib import Path

from .house_defaults import HOUSE_PATH_REWRITES, TEXT_REWRITE_SUFFIXES
from .manifest import PublishManifest, Overlay, read_version

PRESERVE_NAMES = {".git", ".publish"}

# Written into every public tree so verify artifacts never get committed.
PUBLIC_GITIGNORE = """\
# Generated by house publish export — do not commit local verify debris.
__pycache__/
*.py[cod]
*$py.class
.venv/
venv/
.pytest_cache/
.ruff_cache/
*.egg-info/
dist/
build/
.publish/
.DS_Store
*.db
*.pkl
.env
.env.*
!.env.example
"""

# Directory basenames removed from the working tree after verify, before git add.
SCRUB_DIR_NAMES = {
    "__pycache__",
    ".pytest_cache",
    ".ruff_cache",
    ".venv",
    "venv",
}


def _denied(rel: str, deny: list[str]) -> bool:
    rel_posix = rel.replace("\\", "/")
    for pat in deny:
        p = pat.replace("\\", "/").rstrip("/")
        if pat.endswith("/") or pat.endswith("\\"):
            if rel_posix == p or rel_posix.startswith(p + "/"):
                return True
        if fnmatch.fnmatch(rel_posix, pat.replace("\\", "/")):
            return True
        # also match basename for patterns like _tmp_*
        if fnmatch.fnmatch(Path(rel_posix).name, pat.replace("\\", "/")):
            return True
    return False


def _iter_allow_files(private_root: Path, allow: list[str], deny: list[str]) -> list[tuple[Path, str]]:
    """Return (abs_src, rel_posix) pairs."""
    out: list[tuple[Path, str]] = []
    seen: set[str] = set()
    for entry in allow:
        src = private_root / entry
        if not src.exists():
            continue
        if src.is_file():
            rel = entry.replace("\\", "/")
            if _denied(rel, deny):
                continue
            if rel not in seen:
                seen.add(rel)
                out.append((src, rel))
            continue
        for path in src.rglob("*"):
            if not path.is_file():
                continue
            rel = path.relative_to(private_root).as_posix()
            if _denied(rel, deny):
                continue
            # also deny if any parent segment matches deny dir patterns
            if rel not in seen:
                seen.add(rel)
                out.append((path, rel))
    return out


def _clear_public_except_preserve(public_root: Path) -> None:
    if not public_root.exists():
        public_root.mkdir(parents=True, exist_ok=True)
        return
    for child in public_root.iterdir():
        if child.name in PRESERVE_NAMES:
            continue
        if child.is_dir():
            shutil.rmtree(child)
        else:
            child.unlink()


def _should_rewrite_text(path: Path) -> bool:
    name = path.name.lower()
    if name in {".gitignore", ".gitattributes", ".editorconfig", "license", "version"}:
        return True
    return path.suffix.lower() in TEXT_REWRITE_SUFFIXES


def _rewrite_house_paths(text: str) -> str:
    for old, new in HOUSE_PATH_REWRITES:
        text = text.replace(old, new)
    return text


def _copy_file(src: Path, dest: Path) -> None:
    dest.parent.mkdir(parents=True, exist_ok=True)
    if _should_rewrite_text(src):
        try:
            raw = src.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            shutil.copy2(src, dest)
            return
        dest.write_text(_rewrite_house_paths(raw), encoding="utf-8", newline="\n")
        try:
            shutil.copystat(src, dest)
        except OSError:
            pass
        return
    shutil.copy2(src, dest)


def _apply_overlay(private_root: Path, public_root: Path, ov: Overlay) -> None:
    src = private_root / ov.src
    if not src.is_file():
        raise FileNotFoundError(f"overlay source missing: {src}")
    dest = public_root / ov.dest
    _copy_file(src, dest)


def scrub_verify_artifacts(public_root: Path) -> int:
    """Delete caches / venvs left by verify so `git add -A` cannot stage them.

    Returns number of directories removed. Relies on PUBLIC_GITIGNORE as a
    second line of defense for anything left behind.
    """
    if not public_root.is_dir():
        return 0
    git_dir = public_root / ".git"
    targets: list[Path] = []
    for path in public_root.rglob("*"):
        if not path.is_dir():
            continue
        if git_dir in path.parents or path == git_dir:
            continue
        name = path.name
        if name in SCRUB_DIR_NAMES or name.endswith(".egg-info"):
            targets.append(path)
    # deepest first so nested __pycache__ under a package is gone before parents
    targets.sort(key=lambda p: len(p.parts), reverse=True)
    removed = 0
    for path in targets:
        if path.exists():
            shutil.rmtree(path, ignore_errors=True)
            removed += 1
    return removed


def _private_sha(private_root: Path) -> str:
    try:
        r = subprocess.run(
            ["git", "-C", str(private_root), "rev-parse", "--short", "HEAD"],
            check=True,
            capture_output=True,
            text=True,
        )
        return r.stdout.strip() or "unknown"
    except (subprocess.CalledProcessError, FileNotFoundError):
        return "unknown"


def export_tree(m: PublishManifest, *, dry_clear: bool = True) -> dict:
    """Export allowlist + overlays into public_root. Returns status dict."""
    m.public_root.mkdir(parents=True, exist_ok=True)
    if dry_clear:
        _clear_public_except_preserve(m.public_root)

    copied: list[str] = []
    for src, rel in _iter_allow_files(m.private_root, m.allow, m.deny):
        dest = m.public_root / rel
        _copy_file(src, dest)
        copied.append(rel)

    for ov in m.overlays:
        _apply_overlay(m.private_root, m.public_root, ov)
        copied.append(f"{ov.src}->{ov.dest}")

    for rw in m.rewrites:
        _apply_overlay(m.private_root, m.public_root, rw)
        copied.append(f"rewrite:{rw.src}->{rw.dest}")

    gitignore = m.public_root / ".gitignore"
    gitignore.write_text(PUBLIC_GITIGNORE, encoding="utf-8")
    copied.append(".gitignore")

    meta = {
        "project": m.project,
        "version": read_version(m),
        "private_sha": _private_sha(m.private_root),
        "exported_at": datetime.now(timezone.utc).isoformat(),
        "file_count": len(copied),
        "files": copied,
    }
    state_dir = m.public_root / ".publish"
    state_dir.mkdir(exist_ok=True)
    (state_dir / "last_export.json").write_text(json.dumps(meta, indent=2) + "\n", encoding="utf-8")
    # also mirror under private plan/publish if present
    priv_state = m.private_root / "plan" / "publish"
    if (m.private_root / "plan").is_dir():
        priv_state.mkdir(parents=True, exist_ok=True)
        (priv_state / "last_export.json").write_text(json.dumps(meta, indent=2) + "\n", encoding="utf-8")
    return meta
